class Order {
    final int total;
    Order(int total) { this.total = total; }
}
class Customer {
    java.util.List<Order> orders = new java.util.ArrayList<>();
    void add(Order order) { orders.add(order); }
}
enum Phase { NEW, SENT }
public class Main {
    public static void main(String[] args) {
        Customer customer = new Customer();
        customer.add(new Order(3));
        customer.add(new Order(6));
        int sum = 0;
        for (Order order : customer.orders) sum += order.total;
        System.out.println(sum);
        System.out.println(Phase.SENT + " " + java.time.LocalDate.of(2023, 2, 1));
    }
}

